insert into public.academy_course_structures
    (app_slug, tier, structure, content_version)
insert into public.academy_quiz_questions
    (app_slug, tier, scope, module_key, ord, prompt, options, answer_index, explanation)
values
  ('heattransfer', 'advanced', 'module', 'm01-rating-and-the-other-question', 1, 'Effectiveness is a fraction of a maximum. What is that maximum formed from?', '["The larger of the two capacity rates, multiplied by the difference between the two inlet temperatures.", "The smaller of the two capacity rates, multiplied by the difference between the two inlet temperatures.", "The smaller of the two capacity rates, multiplied by the log mean driving force of the unit.", "UA for the unit as built, multiplied by the difference between the two inlet temperatures."]'::jsonb, 1, 'Nothing about the arrangement enters the maximum. The arrangement enters the fraction, which is why one NTU and one capacity ratio give three different answers.'),
  ('heattransfer', 'advanced', 'module', 'm01-rating-and-the-other-question', 2, 'At an NTU of 1.400000 and a capacity ratio of 0.650000 the three arrangements answer 0.643699, 0.545902 and 0.588924. Which figure belongs to the 1-2 shell unit?', '["0.643699, which is the highest of the three at this NTU and capacity ratio.", "0.545902, which is the lowest of the three at this NTU and capacity ratio.", "0.588924 belongs to parallel flow here and 0.545902 to the 1-2 shell unit.", "0.588924, which falls between the other two figures."]'::jsonb, 3, 'Counter-current leads at 0.643699 and parallel trails at 0.545902. A 1-2 shell unit sits between the two arrangements, because one tube pass runs against the shell flow and the other runs with it, and 0.588924 sits between them accordingly.'),
  ('heattransfer', 'advanced', 'module', 'm01-rating-and-the-other-question', 3, 'A counter-current rating at a capacity ratio of 0.350000 comes back with its ceiling field. What does that field carry?', '["No number at all, because this arrangement has no ceiling below one.", "0.740741, which is the effectiveness a counter-current unit cannot pass at this capacity ratio.", "0.830054, which counter-current flow shares with a 1-2 shell unit at this capacity ratio.", "1.000000, which is the ceiling every arrangement carries at every capacity ratio."]'::jsonb, 0, '0.740741 is the parallel ceiling at 0.350000 and 0.830054 is the 1-2 shell ceiling there. Counter-current reports none. Every arrangement carries 1.000000 only at a capacity ratio of 0.000000.'),
  ('heattransfer', 'advanced', 'module', 'm01-rating-and-the-other-question', 4, 'At a capacity ratio of 1.000000, which pair of ceilings does the engine report?', '["Parallel 0.585786 and 1-2 shell 0.500000.", "Parallel 0.606061 and 1-2 shell 0.703560.", "Parallel 0.500000 and 1-2 shell 0.585786.", "Parallel 0.500000 and 1-2 shell 0.703560."]'::jsonb, 2, 'The 1-2 shell ceiling stands above the parallel one on every row where the two differ, so 0.585786 is the shell figure. The pair 0.606061 and 0.703560 belongs to a capacity ratio of 0.650000.'),
  ('heattransfer', 'advanced', 'module', 'm01-rating-and-the-other-question', 5, 'Asked for an effectiveness of 0.999990 at a capacity ratio of 0.650000, what do the three arrangements do?', '["All three answer, and the counter-current figure of 29.894634 is the smallest of the three NTUs returned.", "Counter-current answers with an NTU of 29.894634, and the other two refuse, each carrying its own ceiling.", "All three refuse, because no arrangement reaches an effectiveness of 0.999990 at any area whatsoever.", "Counter-current refuses because the request sits above one minus the capacity ratio, and the other two answer."]'::jsonb, 1, 'The counter-current column answers at 0.900000, 0.990000, 0.999000 and 0.999990. The other two stop at 0.606061 and 0.703560 however high the request goes, because those ceilings depend on the capacity ratio alone.'),
  ('heattransfer', 'advanced', 'module', 'm01-rating-and-the-other-question', 6, 'A rating asked at a capacity ratio of 1.400000 is refused. What does the refusal say about the input?', '["That a capacity ratio above one is a temperature cross, so the two outlet temperatures the case implies come back beside the message as evidence.", "That the engine has clamped the value to one and answered at a capacity ratio of 1.000000, with the clamp recorded in a field of its own.", "That the value sits outside the bound of 1 to 6 this module declares for that input.", "That the ratio is the smaller capacity rate over the larger by definition, so a value above one means the two rates were passed the wrong way round."]'::jsonb, 3, 'Clamping would have produced a plausible effectiveness for a machine with its streams swapped, which is the kind of answer nobody checks. The refusal names the definition instead.'),
  ('heattransfer', 'advanced', 'module', 'm01-rating-and-the-other-question', 7, 'The engine takes an effectiveness out of an NTU and then recovers the NTU from that effectiveness, and the figure it started with comes back on every published row. What has that established?', '["That the closed form for effectiveness carries the right constants, since a wrong constant would break the round trip.", "That the engine agrees with the published file, since the published file is written by the same inversion.", "That the algebra was not mistyped twice in opposite directions, and nothing further.", "That all three arrangements agree at both ends of the capacity ratio range."]'::jsonb, 2, 'An identity between a function and its own inverse holds whether or not either one is correct. Put a wrong constant in the closed form, invert that same wrong form, and the round trip still closes.'),
  ('heattransfer', 'advanced', 'module', 'm01-rating-and-the-other-question', 8, 'Where do this module''s published effectivenesses actually come from?', '["An oracle that marches the two-stream system with a fourth-order scheme and a linear shot, and marches a three-stream system with the tube turn-around as a boundary condition for the shell form.", "The engine''s own closed forms, restated in SI units and converted back to field units.", "The engine''s own closed forms, inverted once so that the recovered NTU can be printed beside the input.", "A published chart for this class of exchanger, read at each NTU and capacity ratio in the file."]'::jsonb, 0, 'Neither oracle route evaluates the closed form the engine uses. That is what makes a golden figure standing beside an engine figure two methods meeting rather than one method restated.'),
  ('heattransfer', 'advanced', 'module', 'm01-rating-and-the-other-question', 9, 'Parallel flow at a capacity ratio of 0.650000 returns 0.597755 at an NTU of 2.600000, 0.605699 at 4.500000 and 0.606059 at 8.000000. What is the figure 0.606061?', '["The effectiveness the same unit reaches once the NTU passes 16.742253.", "The ceiling that column is approaching, which is where the relation itself is heading.", "The counter-current effectiveness at the same capacity ratio and an NTU of 8.000000.", "The 1-2 shell ceiling at the same capacity ratio, which parallel flow approaches from below."]'::jsonb, 1, 'Counter-current at that capacity ratio and an NTU of 8.000000 gives 0.977841, and the 1-2 shell ceiling there is 0.703560. Adding surface past 0.606059 buys effectiveness in the sixth decimal place.'),
  ('heattransfer', 'advanced', 'module', 'm01-rating-and-the-other-question', 10, 'A parallel unit refused at a capacity ratio of 0.650000 reports that it cannot exceed an effectiveness of 0.606. What does a caller that displays only the message throw away?', '["The arrangement, which this engine reports only in the field beside the message.", "Nothing, because 0.606 and 0.606061 are the same figure at the precision the engine works to.", "The 1-2 shell ceiling of 0.703560, which the same refusal carries beside the parallel one.", "The evidence field, which carries the same ceiling as 0.606061 at full precision."]'::jsonb, 3, 'The message rounds to three decimals so it reads. The number a designer needs is the one in the field, and a 1-2 shell request is a separate call with a separate refusal.'),
  ('heattransfer', 'advanced', 'module', 'm01-rating-and-the-other-question', 11, 'A rating of a real machine starts from UA rather than from an NTU. How does the NTU follow?', '["Divide UA by the larger of the two capacity rates.", "Divide UA by the difference between the two inlet temperatures.", "Divide UA by the smaller of the two capacity rates.", "Multiply UA by the capacity ratio of the unit."]'::jsonb, 2, 'NTU is the coefficient times the area over the smaller capacity rate, which is why the hot-day module in this tier holds UA and never computes an area at all.'),
  ('heattransfer', 'advanced', 'module', 'm01-rating-and-the-other-question', 12, 'At a capacity ratio of 0.000000 the ceiling field carries 1.000000 for all three arrangements, counter-current included. Why is that consistent with counter-current flow having no ceiling anywhere else?', '["One is the value the relation approaches there, so the field reports a limit rather than a bound.", "At that capacity ratio only the counter-current relation is defined, so the other two entries are copies of it.", "The engine prints 1.000000 wherever it has no ceiling to report, and leaves the field empty only above a ratio of zero.", "A capacity ratio of 0.000000 turns every arrangement into parallel flow, and the parallel ceiling there is 1.000000."]'::jsonb, 0, 'With nothing limiting the cold side there is no arrangement penalty left to pay. The empty field elsewhere says the relation approaches nothing below one, and here it approaches one.'),
  ('heattransfer', 'advanced', 'module', 'm01-rating-and-the-other-question', 13, 'Read the effectiveness table down a column and then across a row. What two directions does it show?', '["Effectiveness rises with NTU, and it rises again as the capacity ratio rises.", "Effectiveness rises with NTU, and it falls as the capacity ratio rises.", "Effectiveness falls with NTU, and it falls further as the capacity ratio rises.", "Effectiveness rises with NTU, and it does not depend on the capacity ratio at all."]'::jsonb, 1, 'Counter-current at a capacity ratio of 0.350000 runs 0.213502 at an NTU of 0.250000 up to 0.996407 at 8.000000. At a fixed NTU of 1.400000 counter-current runs 0.753403, 0.695454, 0.643699 and 0.583333 as the ratio rises.'),
  ('heattransfer', 'advanced', 'module', 'm01-rating-and-the-other-question', 14, 'Why does this module report a fraction and let the duty follow from it?', '["A fraction can be compared between arrangements and a duty cannot, because a duty carries units and a fraction does not.", "A duty would need the cross-flow correction this module cannot source, and a fraction needs no correction at all.", "A fraction is what the published file records, so a duty would have to be converted before it could be checked.", "A duty depends on the inlet temperatures of the day and a fraction does not, so a fixed surface and fixed flows hold the fraction while the weather moves."]'::jsonb, 3, 'That is exactly what the hot-day rating in this tier turns on. Fix the surface and the air mass and the fraction holds at every ambient.'),
  ('heattransfer', 'advanced', 'module', 'm01-rating-and-the-other-question', 15, 'Counter-current flow returns an NTU of 29.894634 for an effectiveness of 0.999990. What is that figure?', '["A refusal expressed as a number, which this engine returns for counter-current flow in place of the named error string the other two arrangements carry.", "The largest NTU counter-current flow can carry at a capacity ratio of 0.650000.", "A real number and a ruinous design, returned because the relation has a value there and the size of it is what a designer needs.", "The NTU at which counter-current flow finally meets the 1-2 shell ceiling of 0.703560."]'::jsonb, 2, 'Each extra nine of effectiveness costs more surface than the nine before it. The limit on this arrangement is a budget rather than a physical bound, and the module leaves that judgement where it belongs.'),
  ('heattransfer', 'advanced', 'module', 'm02-limits-that-discriminate', 1, 'A capacity ratio of 0.000000 describes which stream?', '["One whose capacity rate matches the capacity rate of the other stream exactly, so that neither of the two can pull ahead of the other.", "One that absorbs heat without changing temperature, such as a boiling liquid or a condensing vapour.", "One with no flow at all, which this engine refuses rather than rates.", "One passing over a surface of zero area, so that the NTU is zero with it."]'::jsonb, 1, 'Its capacity rate is effectively unbounded, so the ratio of the smaller to the larger goes to nothing. A capacity ratio of 1.000000 is the case where the two rates match.'),
  ('heattransfer', 'advanced', 'module', 'm02-limits-that-discriminate', 2, 'At a capacity ratio of 0.000000 and an NTU of 1.400000 the engine returns 0.753403. What happens to that figure if the arrangement is changed?', '["It falls to 0.628836 for parallel flow and to 0.659770 for a 1-2 shell unit.", "It falls to 0.545902 for parallel flow and to 0.588924 for a 1-2 shell unit.", "It is refused for parallel flow, since a ratio of zero puts the request above the parallel ceiling.", "Nothing, because all three arrangements return 0.753403 there."]'::jsonb, 3, 'The figures 0.628836 and 0.659770 belong to a capacity ratio of 0.350000, and 0.545902 and 0.588924 to 0.650000. At a ratio of zero every row of the sweep carries one figure three times.'),
  ('heattransfer', 'advanced', 'module', 'm02-limits-that-discriminate', 3, 'Why does the arrangement stop mattering at a capacity ratio of zero?', '["A stream that does not change temperature has no ends to pair, so it presents the same temperature everywhere along the bundle.", "The driving force collapses to nothing, so every arrangement delivers the same effectiveness of zero.", "The engine routes all three arrangements through the counter-current branch once the ratio reaches zero.", "A capacity ratio of zero puts every arrangement at its ceiling, and every ceiling there is 1.000000."]'::jsonb, 0, 'An arrangement is bookkeeping about which fluid has already been warmed by the time it meets a given piece of metal. Remove the warming and the bookkeeping has nothing to record.'),
  ('heattransfer', 'advanced', 'module', 'm02-limits-that-discriminate', 4, 'The collapse table carries a column reporting whether the three arrangements are equal on each row. Why report that rather than print the three figures and stop?', '["Because the three figures are rounded for display at six decimals, and the underlying values differ from one another in digits the table does not print at all.", "Because the engine cannot return three arrangements on one call, so the equality is asserted in place of the third figure.", "A table a reader has to scan for a mismatch by eye is scanned carefully once, and a table carrying its own verdict is re-checked on every rebuild.", "Because the equality holds only at some of the six NTU values in the sweep, and the column says which."]'::jsonb, 2, 'The equality is asked of the engine rather than asserted by whoever wrote the table down, and it reads yes on every row of the sweep.'),
  ('heattransfer', 'advanced', 'module', 'm02-limits-that-discriminate', 5, 'What makes a check discriminating?', '["It passes on every published case in the file.", "A plausible error changes its outcome.", "It is run on every rebuild rather than once at review.", "It compares the engine against a second implementation."]'::jsonb, 1, 'Passing is a weaker requirement than discriminating. A second implementation that shares a constant with the first cannot fail for the reason that matters, which is why moving the wall factor of two the same way in both files leaves every published case green.'),
  ('heattransfer', 'advanced', 'module', 'm02-limits-that-discriminate', 6, 'Imagine a mistyped coefficient in the 1-2 shell closed form alone. How does the collapse row expose it when an ordinary case at a capacity ratio of 0.650000 does not?', '["At the collapse all three branches share one piece of code, so a mistyped coefficient there breaks every arrangement at once and is impossible to miss.", "At the collapse the engine compares its answer against the published file, and at 0.650000 there is no published row to compare against.", "At the collapse the effectiveness is 1.000000 by definition, so any departure from one is the error itself.", "At the collapse the row must carry one figure three times, so a single wrong branch turns the equality report from yes to no. At 0.650000 the three legitimately differ, so nothing says which figure the odd one should have been."]'::jsonb, 3, 'A wrong constant in any one of the three breaks the row it sits on and leaves the other two untouched. That is exactly the kind of error a single case cannot find.'),
  ('heattransfer', 'advanced', 'module', 'm02-limits-that-discriminate', 7, 'The ceilings pin the closed forms at the other end of the range. What does a wrong constant in the parallel form show up as?', '["A refusal on every request above the ceiling rather than below it.", "An effectiveness above 1.000000 at a high enough NTU.", "A column heading for a ceiling it never arrives at.", "A ceiling reported for counter-current flow as well as for the other two."]'::jsonb, 2, 'Parallel flow at a capacity ratio of 0.650000 runs 0.597755 at an NTU of 2.600000 and 0.606059 at 8.000000, against a ceiling of 0.606061. Neither check needs a figure from outside this repository.'),
  ('heattransfer', 'advanced', 'module', 'm02-limits-that-discriminate', 8, 'Rank the three grades of check this module uses, from weakest to strongest where the method itself is what is in doubt.', '["A restatement, then an independent route, then an analytic limit.", "An analytic limit first, then a restatement, and an independent route last of the three.", "An independent route, then an analytic limit, and a restatement last.", "A restatement, then an analytic limit, then an independent route."]'::jsonb, 0, 'A restatement puts the form under test on both sides. An independent route can fail for a reason that matters. An analytic limit is true independently of both implementations.'),
  ('heattransfer', 'advanced', 'module', 'm02-limits-that-discriminate', 9, 'The wall term in this module''s coefficient carries a factor of two. Move that factor the same way in the engine and in the oracle. What happens to the published cases?', '["The bundle cases fail while the coefficient cases pass.", "Every one of them stays green, and the agreement is the finding rather than the reassurance.", "The engine and the oracle part company in the last digits.", "Every one of them fails, because the oracle derives the wall term from the flat plate rather than from the cylinder."]'::jsonb, 1, 'Both files now say the same wrong thing. The thin-wall limit is what catches it, because a thin cylindrical wall has to collapse onto a flat plate and a flat plate has no factor of two to argue about.'),
  ('heattransfer', 'advanced', 'module', 'm02-limits-that-discriminate', 10, 'The wall resistance over the flat plate is 1.127984 at one wall thickness and 1.002005 at another. Which figure belongs to the thinner wall?', '["1.127984, because a thin wall carries proportionally more curvature than a thick one.", "1.127984, because the flat plate is the limit a thick wall approaches rather than a thin one.", "Neither, since that pair is measured at two conductivities.", "1.002005, because the two expressions converge as the wall thins."]'::jsonb, 3, 'The ratio runs 1.127984, 1.036724, 1.010135 and 1.002005 as the wall thins, at one conductivity throughout. That is the limit fixing the factor of two.'),
  ('heattransfer', 'advanced', 'module', 'm02-limits-that-discriminate', 11, 'The published case file for this module carries how many sections and rows, and what does it declare about itself?', '["19 sections and 75 rows, declared as taken from the literature for every section in the file except the air cooler, whose rows it builds itself.", "12 sections and 45 rows, declared synthetic because the oracle and the engine share a source.", "19 sections and 75 rows, declared synthetic because this repository carries no published heat exchanger case.", "19 sections and 75 rows, declared provisional until the held register is emptied."]'::jsonb, 2, 'Inventing a citation would have been worse than saying so, because a fabricated source is quoted onward by readers who cannot check it and the invention travels further than the number.'),
  ('heattransfer', 'advanced', 'module', 'm02-limits-that-discriminate', 12, 'What is a golden figure in this module?', '["The oracle''s answer, reached by a different route from the engine''s, so that a golden column beside an engine column is two methods meeting.", "The engine''s own answer, recorded once so that a later change to the engine shows up as a difference.", "A figure taken from a publication, which is why the file can be used to validate the engine.", "The average of the engine and the oracle, recorded to the digits the two agree to."]'::jsonb, 0, 'For the log mean the oracle integrates the driving force and never evaluates a logarithm. For the bundle it bisects on the diameter. For the hot day it bisects the surface equation and never touches the effectiveness relation.'),
  ('heattransfer', 'advanced', 'module', 'm02-limits-that-discriminate', 13, 'Three things stand in for publication here. Which of them catches a wrong form that both files hold?', '["An independent route.", "An analytic limit.", "A constant pinned by literal.", "A published row in the golden file."]'::jsonb, 1, 'An independent route catches a wrong implementation of a form both files agree about. A pin catches a change nobody meant to make. There is no published row in this file at all, since it is declared synthetic.'),
  ('heattransfer', 'advanced', 'module', 'm02-limits-that-discriminate', 14, 'The published file carries a row in each of the three arrangements at a capacity ratio of 0.000000. At an NTU of 1.500000 what effectiveness do those rows carry?', '["0.753403 for counter-current and lower figures for the other two.", "0.999665, which is the value the collapse reaches by that NTU.", "0.776870, the same figure in all three.", "0.527633, the same figure in all three."]'::jsonb, 2, 'The collapse is in the committed data rather than only in a table, and 0.753403 is the collapse figure at an NTU of 1.400000 while 0.527633 is the one at 0.750000.'),
  ('heattransfer', 'advanced', 'module', 'm02-limits-that-discriminate', 15, 'Nothing in this course grades a held item, a fitted constant or a film coefficient. What is that a consequence of?', '["A policy that grades only figures the engine returns on more than one door.", "The capstone carrying its own units, which read none of the module''s constants.", "The held register carrying more entries than the module''s own header sentence states.", "The same honesty that declared the file synthetic, since a number nothing can validate is a number nobody should be marked against."]'::jsonb, 3, 'It is a consequence rather than a separate rule. The register entries are taught as stated limits and never as answers.'),
  ('heattransfer', 'advanced', 'module', 'm03-the-air-cooler', 1, 'The studio bay has a design ambient of 95.000000 degF and an air rise of 30.000000 degF, and ANTAN has 98.000000 degF and 26.000000 degF. What air outlet does each report?', '["95.000000 degF and 98.000000 degF, because the air leaves at the ambient it arrived at.", "85.263896 degF and 82.901805 degF, which the engine reports as the air leaving temperature.", "125.000000 degF and 124.000000 degF.", "150.000000 degF and 158.000000 degF, because the air leaves at the temperature the process leaves at."]'::jsonb, 2, 'The air outlet is the ambient plus the rise, which the two columns show directly. The figures 85.263896 and 82.901805 are the two log means, and 150.000000 and 158.000000 are the process outlets.'),
  ('heattransfer', 'advanced', 'module', 'm03-the-air-cooler', 2, 'On the studio bay, 2777777.7778 lb an hour of air carries 20000000.0000 Btu an hour across a rise of 30.000000 degF. What does that let a reader measure?', '["The air heat capacity of 0.240000 Btu per lb per degF the module declares, taking the duty over the air mass and the rise.", "The bare surface of 52125.749338 ft2, since a duty over a mass flow and a temperature change is an area.", "The air density of 0.071524401 lb per ft3 at the fan inlet, which follows from the same three figures.", "The log mean of 85.263896 degF, which the engine forms from the duty and the air mass together."]'::jsonb, 0, 'Measuring a constant out of an answer is worth more than quoting it from a source file, because the measurement tests the path the constant travels on.'),
  ('heattransfer', 'advanced', 'module', 'm03-the-air-cooler', 3, 'What computes the air rise on an air cooler in this module?', '["The duty and the air mass, taken together with the declared air heat capacity.", "The design ambient and the log mean, which fix the air outlet between them.", "The bare surface and the coefficient, through the driving force they produce.", "Nothing, because it is an input."]'::jsonb, 3, 'It is a trade rather than a result: a larger rise needs less air and more bundle, and a smaller rise the reverse. A sheet that does not say which rise it assumed has not said what machine it describes.'),
  ('heattransfer', 'advanced', 'module', 'm03-the-air-cooler', 4, 'The same bay is reported at 94.003933 brake horsepower and at 99.088250. What distinguishes the two figures?', '["The barometric pressure, which stands at 14.700000 psia in one case and at 14.300000 psia in the other.", "The draft type, which puts the fan inlet at 95.000000 degF in one machine and at 125.000000 degF in the other.", "The check ambient, which is the design ambient in one case and a hot afternoon in the other.", "The fan efficiency, which the module declares at 0.650000 and a study may state for itself."]'::jsonb, 1, 'A forced-draft fan sits below the bundle and handles ambient air. An induced-draft fan sits above it and handles the heated air leaving. Nothing about the bundle changed between the two rows.'),
  ('heattransfer', 'advanced', 'module', 'm03-the-air-cooler', 5, 'Which figure is the fan power ratio of 1.054086 formed from?', '["The forced-draft brake horsepower divided by the induced-draft one on the same bay.", "The induced-draft brake horsepower divided by the forced-draft one on the same bay.", "The motor horsepower divided by the brake horsepower on the forced-draft row.", "The induced-draft air density divided by the forced-draft air density."]'::jsonb, 1, 'That ratio is computed rather than estimated, and it is the only comparison between the two draft rows this module stands behind.'),
  ('heattransfer', 'advanced', 'module', 'm03-the-air-cooler', 6, 'Why does the answer carry the fan inlet temperature back with it?', '["So the air density can be recomputed if the barometer is later corrected.", "So the hot-day rating can start from the fan inlet temperature.", "So the horsepower is attributable to one machine rather than the other.", "So the module can report which of its two heat capacities it used for the air."]'::jsonb, 2, 'Two sheets showing 94.003933 and 99.088250 for the same bay are not in conflict if each one says which machine it belongs to, and they are impossible to reconcile if neither does.'),
  ('heattransfer', 'advanced', 'module', 'm03-the-air-cooler', 7, 'A draft type of balanced is refused. What does the second sentence of that message do?', '["It states the size of the thing the module is declining to assume, at about 5 percent on fan power.", "It names the two whole numbers of fans either side of the value given and declines to round between them.", "It states what the engine used to return for an unrecognised draft type before the repair.", "It hands back the two air densities as evidence so a caller can pick one and call again."]'::jsonb, 0, 'The refusal states the size of the thing it declines to assume, which is what separates a refusal from an obstruction. A default here would have answered a question the caller never asked.'),
  ('heattransfer', 'advanced', 'module', 'm03-the-air-cooler', 8, 'Take one bay from a barometer of 14.700000 psia down to 12.000000 psia. Which direction does each of the density, the volume and the fan power move?', '["The density falls, the volume falls and the fan power falls.", "The density rises and the volume falls with it.", "The density falls, the volume rises and the fan power holds at 84.515865.", "The density falls, the volume rises and the fan power rises."]'::jsonb, 3, 'Three directions with one cause. The density runs 0.071139633 down to 0.058073170, the volume 581948.0744 up to 712886.3911, and the fan power 84.515865 up to 103.531935.'),
  ('heattransfer', 'advanced', 'module', 'm03-the-air-cooler', 9, 'The air density export is asked for at 60.000000 degF and 14.700000 psia. What comes back?', '["0.071524401 lb per ft3, as a bare number rather than as an object.", "0.076341600 lb per ft3, on an object whose error key is null.", "0.076341600 lb per ft3, as a bare number rather than as an object.", "A refusal, because a density needs a barometer and a humidity together."]'::jsonb, 2, 'That export is the one documented exception to this module''s error contract: a leaf correlation has nowhere to put an error key. The figure 0.071524401 is the density at the studio fan inlet of 95.000000 degF.'),
  ('heattransfer', 'advanced', 'module', 'm03-the-air-cooler', 10, 'Two of this module''s exports sit outside its named-error contract. Which two?', '["The air density, and the bay itself, which returns 13 keys and no error key at all.", "The bundle table, and the tube-side film, which returns its evidence in place of a message.", "The air density, and the export that returns the declared bounds this module carries.", "The air density, and the one that hands back a copy of the held bundle table."]'::jsonb, 3, 'The bay answers with an object carrying a named error string like the other doors. The film is one of the three doors that hand back evidence as well as a message, which is a different thing from sitting outside the contract.'),
  ('heattransfer', 'advanced', 'module', 'm03-the-air-cooler', 11, 'The correction factor on both teaching bays comes back empty. What does the module say about the surface it reported?', '["That it is a counter-current-basis surface and a real cross-flow unit needs more.", "That it is a cross-flow surface already, since the counter-current log mean is the conservative one to size on.", "That it is provisional until the check ambient is supplied.", "That it carries the declared 10 percent margin this module applies wherever it cannot source a factor."]'::jsonb, 0, 'The bare surfaces are 52125.749338 and 36660.428319 ft2 against log means of 85.263896 and 82.901805 degF. The number is not wrong, it is a stated basis, and how much more metal a real bay needs is the thing nobody here can state.'),
  ('heattransfer', 'advanced', 'module', 'm03-the-air-cooler', 12, 'What would a silent correction factor of one have hidden?', '["That the log mean was taken in the parallel pairing rather than the counter-current one.", "That the area reported rests on a factor this repository cannot source.", "That the hot-day rating would then have depended on the same missing factor.", "That the coefficient on the bare surface is an input rather than a computed figure."]'::jsonb, 1, 'A silent one produces exactly the same number with none of the warning attached, and a reader has no way to know which of the two they are holding. The honest form of a held item is to name the basis.'),
  ('heattransfer', 'advanced', 'module', 'm03-the-air-cooler', 13, 'Why is the hot-day rating unaffected by the correction factor this bay declines?', '["It is computed at the design ambient, where the correction factor would be 1.000000 in any case.", "It reads the counter-current log mean, which is the pairing a cross-flow correction is defined against.", "It reads UA rather than a surface, and a correction factor acts on a surface rather than on UA.", "It holds effectiveness taken from its definition at the design point, so it assumes no arrangement and applies no correction."]'::jsonb, 3, 'That is the mechanism rather than the conclusion. The one number this module cannot source never enters the rating, which is why a hot-day duty can be trusted further than a design area.'),
  ('heattransfer', 'advanced', 'module', 'm03-the-air-cooler', 14, 'Three of the six refusals a bay carries have a second half that is history. How can a reader tell which three?', '["A frame on the line immediately before each one says so, and the second half of the message names what the engine used to return.", "The three that carry history are the three that hand back evidence beside the message.", "The three that carry history name a number in the message, and the other three name only a box.", "The three that carry history are refused by the bay and the other three by the fan chain beneath it."]'::jsonb, 0, 'A fan efficiency of zero used to return Infinity bhp and a negative fan static pressure a negative horsepower. Only the first half of each message describes the module in use.'),
  ('heattransfer', 'advanced', 'module', 'm03-the-air-cooler', 15, 'A bay refuses. How much does the answer carry besides the message?', '["The 13 keys the bay returns on an answer, with the offending one set to null.", "The input it rejected, echoed on a key of its own so a caller can show it.", "Nothing, because the bay is not one of the three doors that hand back evidence.", "The two air densities, since a refused bay still knows the draft type it was given."]'::jsonb, 2, 'Three of this module''s twelve doors hand back more than a message, which is the numbers that produced the state they refused. The bay is not one of them, so on these six the message is the whole of the answer.'),
  ('heattransfer', 'advanced', 'module', 'm04-the-hot-day', 1, 'A bay is built and the weather changes. What does the plant still own, and what does owning it fix?', '["The duty and the design outlet, which fix the driving force, so they fix UA and the surface behind it.", "The surface and the air mass, which fix UA and both capacity rates, so they fix NTU, the capacity ratio and the effectiveness.", "The log mean and the coefficient, which fix the surface, so they fix the duty at any ambient.", "The air rise and the design ambient, which fix the air outlet, so they fix the effectiveness."]'::jsonb, 1, 'The duty then follows from the difference between the two inlet temperatures alone, and the new process outlet and the new air rise come out with it.'),
  ('heattransfer', 'advanced', 'module', 'm04-the-hot-day', 2, 'Which set of four figures does the studio bay hold at every check ambient?', '["An effectiveness of 0.645161, an NTU of 1.172829, a capacity ratio of 0.300000 and a UA of 234565.8720 Btu an hour per degF.", "An effectiveness of 0.562044, an NTU of 0.928810, a capacity ratio of 0.337662 and a UA of 186968.1844 Btu an hour per degF.", "A duty fraction of 0.903226, a process outlet of 159.677419 degF, an air rise of 27.096774 degF and a UA of 234565.8720.", "A log mean of 85.263896 degF, a bare surface of 52125.749338 ft2, an air mass of 2777777.7778 lb an hour and a rise of 30.000000 degF."]'::jsonb, 0, 'The second set is ANTAN''s. The third is one afternoon on the studio bay rather than the machine, and the fourth is its design sheet.'),
  ('heattransfer', 'advanced', 'module', 'm04-the-hot-day', 3, 'The effectiveness this rating holds is not read off an arrangement relation. Where does it come from?', '["From the counter-current closed form, evaluated at the NTU and the capacity ratio the design point produces.", "From the 1-2 shell closed form, which is the arrangement an air cooler bundle most nearly resembles.", "From the published file, which carries an effectiveness column beside the duty fraction on every row.", "From its definition at the design point: the design duty over the smaller capacity rate times the span between the two inlet temperatures."]'::jsonb, 3, 'Because it is a definition rather than a closed form, this rating assumes no arrangement and applies no correction factor, so the one number this module cannot source never enters it.'),
  ('heattransfer', 'advanced', 'module', 'm04-the-hot-day', 4, 'The same bay is rated at coefficients of 4.500000, 5.100000 and 45.000000 on the bare surface. Which columns move?', '["Only the UA, which falls as the surface falls and carries the duty fraction down with it.", "The surface and the duty fraction, since a larger coefficient on less metal delivers less on a hot day.", "Only the surface, which runs 52125.749338, 45993.308239 and 5212.574934 ft2.", "The surface, the UA and the process outlet, which is why a published row has to carry all three."]'::jsonb, 2, 'UA stays at 234565.8720 Btu an hour per degF, the duty fraction at 0.903226 and the process outlet at 159.677419 degF on all three rows. A rating cannot see the coefficient and the area separately at all.'),
  ('heattransfer', 'advanced', 'module', 'm04-the-hot-day', 5, 'The published hot-day rows carry UA and no overall coefficient. What is that?', '["A statement about the calculation rather than an omission in the file.", "An omission, which the file records in its held register as unsourced.", "A consequence of the coefficient being fitted, which no oracle can validate.", "A convention that keeps the published rows shorter than the engine''s answer."]'::jsonb, 0, 'UA is the duty over the design log mean, so a hot-day rating cannot see U and the area separately. Rating the same bay at three different coefficients moves the surface column and nothing else.'),
  ('heattransfer', 'advanced', 'module', 'm04-the-hot-day', 6, 'At a check ambient of 92.000000 degF the studio bay reports a duty of 20387096.7742 Btu an hour. What process outlet goes with it?', '["144.193548 degF.", "148.064516 degF.", "151.935484 degF.", "150.000000 degF, held while the duty moves."]'::jsonb, 1, 'The outlet of 144.193548 degF belongs to an ambient of 86.000000 degF and 151.935484 degF to 98.000000 degF. A held outlet beside a moving duty is the state this rating was repaired to stop reporting.'),
  ('heattransfer', 'advanced', 'module', 'm04-the-hot-day', 7, 'Across the studio sweep the duty falls, the process outlet rises and the air rise falls. Why does the air outlet rise?', '["The air rise is held while the ambient climbs, so the outlet tracks the ambient exactly.", "The air outlet is the process outlet less the approach, and the process outlet rises.", "The ambient underneath it rises further than the rise falls.", "The air mass falls with the duty, so the same heat lands in less air."]'::jsonb, 2, 'The air outlet runs 117.741935 degF at an ambient of 86.000000 up to 148.387097 degF at 124.000000, while the rise falls from 31.741935 to 24.387097 degF. The air mass is held fixed across the whole sweep.'),
  ('heattransfer', 'advanced', 'module', 'm04-the-hot-day', 8, 'The process capacity rate on the studio bay is 200000.0000 and the air capacity rate 666666.6667 Btu an hour per degF. How is each formed?', '["Each from the design duty and the design log mean, divided between the two streams by the capacity ratio.", "Each from UA and the effectiveness, which is the fraction that separates the two streams.", "Each from the air mass of 2777777.7778 lb an hour and the air heat capacity of 0.240000 Btu per lb per degF.", "Each from the design duty and its own temperature change: the process drop for one and the air rise for the other."]'::jsonb, 3, 'Neither rate depends on the ambient, so both can be formed once at the design point and used at every check ambient after that.'),
  ('heattransfer', 'advanced', 'module', 'm04-the-hot-day', 9, 'At the studio bay''s own check ambient the rated duty is 18064516.1290 Btu an hour. Which two products have to reproduce it?', '["The process capacity rate times the design drop, and the air capacity rate times the design rise.", "The process capacity rate times the drop from the inlet to the new outlet, and the air capacity rate times the new rise.", "UA times the design log mean, and the effectiveness times the design duty.", "The duty fraction times the smaller capacity rate, and the same fraction times the larger one."]'::jsonb, 1, 'Both routes give 18064516.1290 Btu an hour. Any rating that hands back a duty, an outlet and a rise has already stated all three, whether it computed them together or not.'),
  ('heattransfer', 'advanced', 'module', 'm04-the-hot-day', 10, 'On a morning at 86.000000 degF the studio bay returns a duty fraction of 1.058065. What is that figure?', '["A capability of the surface rather than a duty that was delivered.", "A delivered duty of 21161290.3226 Btu an hour on the process stream.", "A rating error, which the engine flags by labelling the row colder than design.", "The spare capacity the same bay carries into a hot afternoon."]'::jsonb, 0, 'A plant holding the process at 150.000000 degF will throttle or stage the air instead, and the outlet of 144.193548 degF is what the bundle would reach wide open.'),
  ('heattransfer', 'advanced', 'module', 'm04-the-hot-day', 11, 'ANTAN at 86.000000 degF returns a duty fraction of 1.087591 and at 124.000000 degF returns 0.810219. Why can the first figure not be read as headroom for the second day?', '["The first is computed at a fixed UA and the second at a UA that has been recomputed for the hotter and thinner air.", "The first is a capability and the second is a capability too, so neither is a delivered duty.", "The two figures belong to different days, and the machine delivers what the day it is given allows.", "The first belongs to ANTAN and the second to the studio bay, so the pair cannot be compared."]'::jsonb, 2, 'Read as spare capacity a cold-day fraction is worthless. The studio bay behaves the same way, at 1.058065 on its cold morning and 0.812903 at 124.000000 degF.'),
  ('heattransfer', 'advanced', 'module', 'm04-the-hot-day', 12, 'What changes in the engine''s answer as the check ambient crosses the design ambient of 95.000000 degF?', '["The effectiveness, which is recomputed above the design ambient and held below it.", "The basis string, which names the definition below the design point and the closed form above it.", "The capacity ratio, which the engine takes the other way round once the air is the hotter stream.", "The regime label and the column saying whether the design outlet is reached."]'::jsonb, 3, 'At 86.000000 and 92.000000 degF the rows read colder than design with the design outlet reached. From 98.000000 degF up they read hotter than design and the outlet is not reached.'),
  ('heattransfer', 'advanced', 'module', 'm04-the-hot-day', 13, 'The rated duty and the product of UA with the hot-day log mean are compared on every row of both sweeps. What does that comparison establish?', '["That two independent methods land on one number, which is a thing that could have failed.", "That the effectiveness relation has been correctly inverted, which is what the ratio of one shows.", "That the engine agrees with the published file to the digits the two of them print.", "That UA was held fixed across the sweep, which the flat column already shows."]'::jsonb, 0, 'The effectiveness route never evaluates the surface equation and the surface route never evaluates the effectiveness relation. Every ratio in that column is 1.000000 to the precision printed.'),
  ('heattransfer', 'advanced', 'module', 'm04-the-hot-day', 14, 'The middle column of that check is UA times a log mean. Which log mean?', '["The design one, formed at the design outlet and the design air rise, since UA is held from the design point.", "The hot-day one, formed at the rated outlet and the rated air rise.", "The counter-current one on the design terminals, which is the pairing the bay was sized on.", "The arithmetic mean of the two end differences, which the engine reports beside the log mean."]'::jsonb, 1, 'Taking it at the design values would have turned the check into a restatement. On the studio bay the hot-day log mean runs 90.214702 degF at an ambient of 86.000000 down to 69.311296 degF at 124.000000.'),
  ('heattransfer', 'advanced', 'module', 'm04-the-hot-day', 15, 'At a check ambient of 110.000000 degF the engine gives a duty of 18064516.1290 Btu an hour and the published file 18064516.1306. What are the differing digits?', '["A rounding inside the engine.", "The residual caused by the viscosity conversion this module rounds.", "The point the oracle''s bisection stopped at.", "A disagreement about the effectiveness, which the two reach by different relations."]'::jsonb, 2, 'The oracle bisects on the duty until the surface equation balances and never touches the effectiveness relation. On the same row the duty fraction, the outlet of 159.677419 degF, the rise of 27.096774 degF and the UA of 234565.8720 all agree exactly.'),
  ('heattransfer', 'advanced', 'module', 'm05-what-the-method-does-not-know', 1, 'The engine''s test suite pins dittusBoelterA at 0.023000 by literal. What does that pin establish about the value?', '["That the value has been checked against the oracle, which reaches the same figure by its own route.", "That the value sits inside the validity band this module records for the correlation it belongs to.", "Nothing about the value, because it makes a change to it a reviewed act rather than a silent one.", "That the value has been measured out of an engine answer in the way the viscosity conversion is."]'::jsonb, 2, 'A pinned constant and a validated one both appear as a green line in a test report, and a reader who has not looked at the file will assume the stronger of the two. There is no band recorded here to sit inside.'),
  ('heattransfer', 'advanced', 'module', 'm05-what-the-method-does-not-know', 2, 'Which answer in this module do the pinned correlation coefficients act on?', '["The tube-side film coefficient.", "The bundle diameter and the shell diameter.", "The hot-day duty fraction and the process outlet.", "The fan brake horsepower and the motor horsepower."]'::jsonb, 0, 'They sit on the film and nowhere else. A number nothing can validate should decide as little as possible, and no graded field in this course reads one.'),
  ('heattransfer', 'advanced', 'module', 'm05-what-the-method-does-not-know', 3, 'The held register carries 7 entries and the module''s own header sentence says six. Which governs, and what is the lesson?', '["The header, because a module''s own statement of its contents is its contract with a caller.", "Neither, because the disagreement is itself recorded as an eighth held item in the register.", "The header, because the seventh entry is the fan constant, which is measured rather than held.", "The register, because it is what the returns point at, and a count is worth measuring rather than quoting."]'::jsonb, 3, 'This is the cheapest possible demonstration of measuring a count rather than quoting one, even from the module that owns it.'),
  ('heattransfer', 'advanced', 'module', 'm05-what-the-method-does-not-know', 4, 'Which of these is in the held register?', '["The declared maximum of 6 shell passes, which is a bound rather than a published limit.", "The Sieder-Tate exponent and the band it was fitted over.", "The declared margin of 10 percent below which a controlling verdict carries a note.", "The transition band edges of 2300 and 10000, between which the film is refused."]'::jsonb, 1, 'The register names bundleConstants, dittusBoelterBand, dittusBoelterCoolingExponent, siederTateExponent, crossFlowF, defaultsProvenance and fanConstantWaterDensity. A declared bound is this module''s own choice and it says so.'),
  ('heattransfer', 'advanced', 'module', 'm05-what-the-method-does-not-know', 5, 'The engine carries 2.419100 for the centipoise conversion and the published file carries 2.419088. What is the second figure?', '["The exact derivation, against which the engine''s figure is a rounding.", "The same conversion measured out of an engine answer at a unit viscosity.", "The conversion used on the air density path.", "A second engine constant, used wherever a Prandtl number rather than a Reynolds number is formed."]'::jsonb, 0, 'The ratio between them is 1.000004832191, formed from those two figures, and it is carried in the published file.'),
  ('heattransfer', 'advanced', 'module', 'm05-what-the-method-does-not-know', 6, 'The engine''s gas constant is 10.731600 and the figure derived from the SI gas constant is 10.731577. What ratio does that pair give?', '["1.000004832191.", "A ratio of exactly one, because the two agree at the precision the engine works to.", "1.000002134913.", "0.500000, which is what the Reynolds check on the same path returns."]'::jsonb, 2, 'The figure 1.000004832191 is the viscosity conversion ratio. The Reynolds ratio of 0.500000 is a separate check, on a quantity inversely proportional to viscosity.'),
  ('heattransfer', 'advanced', 'module', 'm05-what-the-method-does-not-know', 7, 'Neither rounding is moved. What is done instead?', '["Each one is pinned by literal, in the same way the correlation coefficients are.", "The residual each one causes downstream is asserted to equal the rounding.", "Each one is recorded in the held register.", "Each one is applied at the exact value in the oracle and at the rounded value in the engine."]'::jsonb, 1, 'Moving either would move every shipped number that reads it. The named cause is then itself a check: if the downstream difference stops matching the rounding, something other than the rounding has changed.'),
  ('heattransfer', 'advanced', 'module', 'm05-what-the-method-does-not-know', 8, 'At a unit viscosity the Prandtl number comes back as 30.238750. What can be recovered from it?', '["The Reynolds number at the same conditions, taking the Prandtl number times the mass flow over the bore.", "The laminar Nusselt number of 3.660000, which the correlation falls back on below a Reynolds number of 2300.", "The gas constant of 10.731600, since a Prandtl number and a gas constant share the same conversion.", "The viscosity conversion the engine used, taking the Prandtl number times the conductivity over the heat capacity."]'::jsonb, 3, 'The heat capacity and the conductivity are conditions of the case, so the conversion is the only unknown left, and it comes back as 2.419100.'),
  ('heattransfer', 'advanced', 'module', 'm05-what-the-method-does-not-know', 9, 'The engine gives a Reynolds number of 22025.923000 at one viscosity and 11012.961500 at twice it. What kind of check is that?', '["A comparison with the published file, since the golden carries both figures.", "A restatement, since the second call reuses the first number with the viscosity divided out.", "An analytic limit, since a Reynolds number inversely proportional to viscosity has to halve.", "A pin, since the ratio of 0.500000 is asserted by literal in the engine gate."]'::jsonb, 2, 'It costs one extra call and it needs no publication. The ratio comes back as 0.500000.'),
  ('heattransfer', 'advanced', 'module', 'm05-what-the-method-does-not-know', 10, 'The Rankine offset lives as a literal inside the air density helper rather than as a row of the declared constants table. How is it recovered?', '["From two density calls, at 0.076341600 and 0.068439697 lb per ft3 for 60.000000 and 120.000000 degF.", "From the gas constant and the molecular weight of air, both of which the declared constants table does carry.", "From the standard barometric base of 14.700000 psia and one density call at that pressure.", "From the published file, which carries the offset beside the water density the fan constant implies."]'::jsonb, 0, 'An ideal-gas density is inversely proportional to absolute temperature, so with two densities at two temperatures the offset is the only unknown left. It comes back as 459.670000 degR.'),
  ('heattransfer', 'advanced', 'module', 'm05-what-the-method-does-not-know', 11, 'The fan constant is written against a water density this module never states. Why does moving that constant in the engine and in the oracle together still fail a gate?', '["The published file pins the constant by literal.", "The oracle''s fan route goes through pascals and reads no customary constant at all.", "The engine reports the implied density on every fan answer.", "The two files carry the constant at different precisions, so moving both leaves them disagreeing."]'::jsonb, 1, 'The implied density of 62.303335 lb per ft3 is a measurement rather than a citation, and the gate asserts it. One of the two files never read the constant, which is what makes the assertion bite.'),
  ('heattransfer', 'advanced', 'module', 'm05-what-the-method-does-not-know', 12, 'This module carries 3 layout angles across 4 pass counts, and at one area of 980.000000 ft2 the second and third layouts return identical figures in all four pass counts. What does the engine do about it?', '["It refuses the second of the two layouts, so that a caller cannot enter an input that does nothing.", "It reports the bundle diameter once and leaves the shell diameter null for the second of the two.", "It records the pair in the held register and returns the layout it was given without a note.", "It compares the two constant rows as data, reports them equal and attaches a note to any answer at either layout."]'::jsonb, 3, 'An input that does nothing is worse than an absent one when it looks live, because a reviewer reads a filled box as a decision. The engine gate asserts the equality so the two rows cannot drift apart and start looking meaningful.'),
  ('heattransfer', 'advanced', 'module', 'm05-what-the-method-does-not-know', 13, 'At the same area and pass count the bundle runs 19.000124 inches at one layout and 20.698071 inches at another, a ratio of 1.089365. What does that pair show?', '["That the two layouts the note calls identical do move the bundle after all, by about 9 percent.", "That the bundle diameter depends on the pass count rather than on the layout angle.", "That the layout input is not decorative in general, so the note names the pair it is inert between.", "That the shell clearance of 2.500000 inches is added twice at one of the two layouts."]'::jsonb, 2, 'The ratio is taken as the second figure over the first. The pair the note calls inert is a different pair, and every figure in it agrees exactly.'),
  ('heattransfer', 'advanced', 'module', 'm05-what-the-method-does-not-know', 14, 'At the studio clearance of 2.500000 inches the shell is 21.500124 inches and at no clearance it is 19.000124. What does the difference show?', '["That the clearance is added once.", "That the clearance is added once to the bundle and once again to the shell.", "That the clearance is a fraction of the bundle rather than a fixed addition to it.", "That the bundle diameter already carries half the clearance before the shell is formed."]'::jsonb, 0, 'The difference is the clearance itself, and the figure at no clearance is the bundle diameter. The clearance is an input because it depends on the head type.'),
  ('heattransfer', 'advanced', 'module', 'm05-what-the-method-does-not-know', 15, 'Before this engine was repaired, the hot-day block held the process outlet temperature fixed and scaled the duty by the ratio of two log means. Why could those two former behaviours not both be true?', '["Because a ratio of two log means is always one, so the duty could never have moved at all.", "If the duty falls the outlet has to rise, because the process capacity rate does not change with the weather.", "Because the old block read a coefficient, and a rating cannot see the coefficient and the area separately.", "Because the outlet was held at a value the old block took from the design ambient rather than the check ambient."]'::jsonb, 1, 'That is history and it is what the engine used to do. The current answer satisfies all three of the duty, the outlet and the rise, at 18064516.1290 Btu an hour, 159.677419 degF and 27.096774 degF on the same row.'),
  ('heattransfer', 'advanced', 'module', 'm06-the-expert-reading', 1, 'On the teaching bay, which of these figures was chosen rather than computed?', '["The air outlet of 125.000000 degF.", "The air rise of 30.000000 degF.", "The log mean of 85.263896 degF.", "The air mass of 2777777.7778 lb an hour."]'::jsonb, 1, 'The rise is a trade rather than a result. The outlet is the ambient plus the rise, the log mean follows from the four terminals, and the air mass follows from the duty and the rise.'),
  ('heattransfer', 'advanced', 'module', 'm06-the-expert-reading', 2, 'Which figure on the same bay is computed rather than given to the module?', '["The coefficient of 4.500000 on the bare surface.", "The barometric pressure of 14.700000 psia.", "The bare surface of 52125.749338 ft2.", "The process outlet of 150.000000 degF at the design point."]'::jsonb, 2, 'The surface is the arithmetic of a duty, a coefficient and a driving force. The coefficient is an input because this module never computes an air-side coefficient from fin geometry.'),
  ('heattransfer', 'advanced', 'module', 'm06-the-expert-reading', 3, 'Work the design point in order. Which sequence needs each step for the one after it?', '["The air outlet, then the log mean, then the bare surface, then the air mass.", "The bare surface, then the log mean, then the air outlet, and the air mass last of all.", "The air mass, then the air outlet, then the surface, then the log mean.", "The log mean, then the air outlet, then the air mass."]'::jsonb, 0, 'On the teaching bay those four are 125.000000 degF, 85.263896 degF, 52125.749338 ft2 and 2777777.7778 lb an hour.'),
  ('heattransfer', 'advanced', 'module', 'm06-the-expert-reading', 4, 'At a check ambient of 112.000000 degF, what does the teaching bay deliver?', '["A duty fraction of 0.812903, a duty of 16258064.5161 Btu an hour, a process outlet of 168.709677 degF and an air rise of 24.387097 degF, which is the hottest row of the sweep.", "A duty fraction of 0.941935, a duty of 18838709.6774 Btu an hour, a process outlet of 155.806452 degF and an air rise of 28.258065 degF, which is the row below it.", "A duty fraction of 0.890323 with the process outlet held at 150.000000 degF and the air rise held at 30.000000 degF.", "A duty fraction of 0.890323, a duty of 17806451.6129 Btu an hour, a process outlet of 160.967742 degF and an air rise of 26.709677 degF."]'::jsonb, 3, 'The first alternative is the row at 124.000000 degF and the second the row at 104.000000 degF. A duty that has fallen with a held outlet and a held rise is the state this rating was repaired to stop reporting.'),
  ('heattransfer', 'advanced', 'module', 'm06-the-expert-reading', 5, 'The hot-day log mean at 112.000000 degF is 75.912371 degF and UA is 234565.8720 Btu an hour per degF. What does their product come to, and what does it check?', '["17806451.6129 Btu an hour, scaled from the design duty.", "16258064.5161 Btu an hour, the duty at 124.000000 degF.", "234565.8720 Btu an hour, because a UA times a log mean returns the UA when the two methods agree.", "17806451.6129 Btu an hour, which is the rated duty reached by the other method."]'::jsonb, 3, 'The effectiveness route never evaluated the surface equation and the surface route never evaluated the effectiveness relation, so the agreement is two methods meeting.'),
  ('heattransfer', 'advanced', 'module', 'm06-the-expert-reading', 6, 'The correction factor on this bay comes back empty. What has to travel with the design surface because of it?', '["The check ambient, because a surface without one is a design figure rather than a rating.", "The word counter-current, because the surface is a counter-current-basis surface.", "The declared margin of 10 percent, because the module applies it wherever a factor is missing.", "The fan inlet temperature, because the surface and the fan power are reported on the same answer."]'::jsonb, 1, 'A caller that copies the area alone onto a sheet has copied a counter-current-basis figure without the sentence that qualifies it, and the sheet then reads as a sized bay.'),
  ('heattransfer', 'advanced', 'module', 'm06-the-expert-reading', 7, 'Why does a study of this kind state its own fan static pressure, fan efficiency and motor efficiency rather than take the module''s 0.600000, 0.650000 and 0.920000?', '["Those three are fitted correlation coefficients, and a fitted number may not appear in a study.", "Those three sit in the held register, and a held item may not be used in a calculation at all.", "Those three name no machine at all, and a pin makes moving one a reviewed act rather than a validation of it.", "Those three are measured out of the engine''s own answers, so a study has to measure them again."]'::jsonb, 2, 'The default wall conductivity of 26 names no material on the same terms. A study that states its own is reporting a fan it has chosen rather than inheriting a number with nothing behind it.'),
  ('heattransfer', 'advanced', 'module', 'm06-the-expert-reading', 8, 'The hot-day block reads no declared constant at all. What follows from that?', '["Nothing held for literature reaches the rated answer.", "The rated answer carries no basis string, since there is no constant to name in one.", "The rated answer has to be checked against the design point before it can be quoted.", "The rated answer is the only one in this module that the published file does not cover."]'::jsonb, 0, 'It takes the surface and the air mass and holds the effectiveness from its definition at the design point, assuming no arrangement and applying no correction factor.'),
  ('heattransfer', 'advanced', 'module', 'm06-the-expert-reading', 9, 'Which of these does this module not do?', '["A tube count.", "A rigorous cross-flow rating.", "A log mean.", "An effectiveness and an NTU in both directions."]'::jsonb, 1, 'The list it declines is a shell-side film from stream analysis, pressure drop, a vibration check, condensation or boiling, fin geometry, and a rigorous cross-flow rating.'),
  ('heattransfer', 'advanced', 'module', 'm06-the-expert-reading', 10, 'Pressure drop in a line and machine work belong to other engines. Which two?', '["The Pipeline and Line Sizing engine, and Separation.", "Separation, and Rotating Equipment.", "Relief and Flare, together with the Pipeline and Line Sizing engine.", "The Pipeline and Line Sizing engine, and Rotating Equipment."]'::jsonb, 3, 'The fan on this bay is one line of arithmetic: a volume, a static pressure and two efficiencies. Fans, pumps and compressors as machines are not attempted here.'),
  ('heattransfer', 'advanced', 'module', 'm06-the-expert-reading', 11, 'The shell-side film coefficient stays an input everywhere in this module. What reason does the module give?', '["The shell-side correlation is in the held register, with its validity band unestablished.", "The shell side is refused rather than defaulted, in the way a cooled tube side is.", "A rigorous shell-side coefficient needs stream analysis that belongs in a dedicated rating package.", "The published file carries no shell-side row, so nothing could check a computed one."]'::jsonb, 2, 'A boundary named is a boundary a caller can plan around, and this one has been stated from the beginning rather than discovered.'),
  ('heattransfer', 'advanced', 'module', 'm06-the-expert-reading', 12, 'This package exports an overall coefficient twice. What separates the two?', '["The reference area, which is the outside tube surface here and a stated bore in the other.", "The direction, since one is the clean coefficient and the other the dirty one.", "The units, since one is in Btu an hour per ft2 per degF and the other in SI units.", "The number of resistances, since one assembles five terms and the other assembles three."]'::jsonb, 0, 'A coefficient without its reference area is not a number anyone can use. This module states its own on every answer.'),
  ('heattransfer', 'advanced', 'module', 'm06-the-expert-reading', 13, 'What should be handed over with a hot-day duty from this bay?', '["The design surface and the coefficient it was formed at, so a reader can recompute UA.", "The check ambient and the design ambient, which are the only two inputs that moved.", "The published row nearest the check ambient, so the reader has a second method beside it.", "The four fixed quantities, the two that moved, and the basis the rating states."]'::jsonb, 3, 'A reader who receives the numbers without those qualifications has been handed a sized bay rather than a rated one.'),
  ('heattransfer', 'advanced', 'module', 'm06-the-expert-reading', 14, 'Which of these is one of the three habits this tier ends on?', '["Prefer a published figure to an analytic limit wherever both are available.", "Ask of any check whether it could have failed for a reason other than a typing error.", "Quote a coefficient without its reference area only when the two areas agree.", "Treat a green test suite as evidence once every case in it has been read."]'::jsonb, 1, 'The other two are computing one number on a result sheet from the others, and separating what a file pins from what a second route or an analytic limit has established.'),
  ('heattransfer', 'advanced', 'module', 'm06-the-expert-reading', 15, 'At 124.000000 degF the teaching bay gives a duty of 16258064.5161 Btu an hour and a hot-day log mean of 69.311296 degF. What does the second-method check do here?', '["It multiplies the duty fraction of 0.812903 by the design duty and lands on the same figure.", "It divides the duty by 69.311296 and compares the result with the bare surface.", "It multiplies UA by 69.311296 and lands on 16258064.5161 Btu an hour.", "It compares 16258064.5161 with the published figure of 18064516.1306."]'::jsonb, 2, 'It is one line and it is the only step in the chain that could have failed for a reason other than a slip of the hand. The published figure of 18064516.1306 belongs to a check ambient of 110.000000 degF.'),
  ('heattransfer', 'advanced', 'final', null, 1, 'A rating and a sizing ask different questions of the same exchanger. What does a rating start from?', '["A surface you already own, and it returns what fraction of the possible heat that surface moves.", "A duty you have specified for two streams, and it returns the surface and the bundle that will deliver it.", "A driving force you have measured, and it returns the coefficient the surface must carry.", "A tube count you have chosen, and it returns the film coefficient that count produces."]'::jsonb, 0, 'Effectiveness is that fraction, and NTU is the surface written dimensionlessly.'),
  ('heattransfer', 'advanced', 'final', null, 2, 'At an NTU of 8.000000 and a capacity ratio of 0.350000 the three arrangements return 0.996407, 0.740726 and 0.829902. Which of those is the parallel figure, and what is it near?', '["0.829902, which is close to the parallel ceiling of 0.830054 at that capacity ratio.", "0.996407, which is close to a ceiling of 1.000000 that parallel flow carries at every ratio.", "0.740726, which is close to the parallel ceiling of 0.740741 at that capacity ratio.", "0.740726, which is close to the 1-2 shell ceiling at that capacity ratio."]'::jsonb, 2, 'The 1-2 shell figure of 0.829902 approaches its own ceiling of 0.830054, and 0.996407 is counter-current, which has no ceiling to approach.'),
  ('heattransfer', 'advanced', 'final', null, 3, 'A 1-2 shell unit is asked for an effectiveness of 0.820000 at a capacity ratio of 0.650000 and refuses. What comes back beside the message?', '["The NTU of 16.742253 the request would have needed.", "The parallel ceiling of 0.606061 for comparison.", "Nothing, since this door carries a message alone.", "The ceiling of 0.703560."]'::jsonb, 3, 'The message itself rounds to 0.704 so that it reads. A caller showing only the message has thrown away the number a designer needs.'),
  ('heattransfer', 'advanced', 'final', null, 4, 'Why is a 1-2 shell ceiling higher than a parallel one at the same capacity ratio?', '["It carries twice the surface for the same shell length, so it reaches further before it flattens.", "One of its tube passes runs against the shell flow and the other runs with it, so it sits between the two arrangements.", "It is corrected by an F factor before the ceiling is reported, and F is at most 1.000000.", "Its shell flow is counter-current throughout, so only the tube turn-around costs it anything."]'::jsonb, 1, 'At a capacity ratio of 0.350000 the pair is 0.740741 and 0.830054, and at 1.000000 it is 0.500000 and 0.585786.'),
  ('heattransfer', 'advanced', 'final', null, 5, 'A counter-current unit is asked for an effectiveness of 0.999000 at a capacity ratio of 0.650000. What does it return?', '["An NTU of 10.210712.", "An NTU of 29.894634.", "An NTU of 16.742253.", "A refusal carrying a ceiling, in the way the other two arrangements do."]'::jsonb, 2, 'The figures 10.210712 and 29.894634 belong to effectivenesses of 0.990000 and 0.999990 on the same column. Each extra nine costs more surface than the one before it.'),
  ('heattransfer', 'advanced', 'final', null, 6, 'What does an arrangement change, and what does it leave alone?', '["It changes the fraction and leaves the maximum alone.", "It changes the maximum and leaves the fraction alone.", "It changes both, because the capacity ratio is taken per arrangement.", "It changes neither, because the capacity ratio and the NTU fix the answer."]'::jsonb, 0, 'The maximum is the smaller capacity rate times the difference between the two inlet temperatures, and nothing about the arrangement enters it.'),
  ('heattransfer', 'advanced', 'final', null, 7, 'The published inversion rows run each direction and the recovered NTU returns the one the row started with. What does this module offer as the actual evidence instead?', '["The pinned constants, which make any change to the closed form a reviewed act.", "The published effectiveness column, which is read from a chart for each arrangement.", "The ceilings, which an inversion cannot reach.", "The oracle''s marches, which never evaluate the closed form the engine uses."]'::jsonb, 3, 'A march of the two-stream system, or of the three-stream shell system with the tube turn-around as a boundary condition, could have failed for a reason other than a typing error.'),
  ('heattransfer', 'advanced', 'final', null, 8, 'Three closed forms in three branches of this code return 0.527633 at one NTU and 0.988891 at another, with the capacity ratio held at zero throughout. What does the arrangement contribute?', '["A difference in the third decimal, which the table reports as equal after rounding.", "Nothing, because all three arrangements return the same figure on every row of that sweep.", "A difference only above an NTU of 2.600000, which is where the two ceilings begin to bite on the answer.", "A difference in the counter-current column alone, which has no ceiling to flatten it."]'::jsonb, 1, 'Three separate closed forms in three separate branches produce one answer, and the engine reports the equality rather than leaving it to be seen.'),
  ('heattransfer', 'advanced', 'final', null, 9, 'Why is a limit where three branches must agree worth more to this module than one more ordinary case?', '["A wrong constant in one branch breaks the row it sits on and leaves the other two untouched, so the disagreement names the branch.", "A limit runs faster than a case, so it can be re-checked on every rebuild rather than at review.", "A limit is published and an ordinary case here is not, so only the limit carries a citation.", "A limit holds at every NTU, so one row of it covers the whole range of the relation."]'::jsonb, 0, 'At a capacity ratio where the three legitimately differ, a wrong figure sits in a column where a different figure is expected and nothing says which of the two it should have been.'),
  ('heattransfer', 'advanced', 'final', null, 10, 'Which claim about this class of calculation is recorded as false, and where had it appeared?', '["That the log mean can equal the arithmetic mean, and it had appeared in the oracle.", "That a capacity ratio may exceed one, and it had appeared in the published file.", "That every arrangement has a ceiling, and it had appeared in the studio help text.", "That a 1-2 shell unit reaches the counter-current answer, and it had appeared in the engine."]'::jsonb, 2, 'Counter-current flow has no ceiling below one, which is an analytic truth about the relation. A default arrangement makes a wrong general claim expensive, because counter-current is what the Rating tab opens on.'),
  ('heattransfer', 'advanced', 'final', null, 11, 'The published file is written by an oracle. For the bundle diameter, what does the oracle do instead of what the engine does?', '["It evaluates the same form in SI units and converts the answer back.", "It reads the pairs from a published table.", "It forms the diameter from the shell diameter less the clearance.", "It bisects on the diameter until the geometry form balances."]'::jsonb, 3, 'Inverting an exponent is one of the easiest errors to make in that expression and one of the hardest to see in an answer, and a bisection cannot make it.'),
  ('heattransfer', 'advanced', 'final', null, 12, 'What can an independent route not catch on its own?', '["A wrong implementation of a form the two files agree about.", "A wrong form that both files hold.", "A slip of the hand in restating an expression in other units.", "An answer that fails to satisfy its own surface equation."]'::jsonb, 1, 'Moving the wall factor of two the same way in the engine and in the oracle leaves every published case green. An analytic limit is what catches it.'),
  ('heattransfer', 'advanced', 'final', null, 13, 'What three things stand in for publication in this module, given that the file is declared synthetic?', '["Route independence, the constant pins, and the analytic limits.", "Route independence, the held register, and the declared bounds.", "The constant pins, the held register, and the inversion checks.", "The analytic limits, the inversion checks, and the measured roundings."]'::jsonb, 0, 'Any figure in the file rests on at least one of the three, and a reader is entitled to ask which. The held register records what none of the three can reach.'),
  ('heattransfer', 'advanced', 'final', null, 14, 'One of the analytic limits this module leans on is self-consistency across the whole chain. What does that limit fix?', '["A wall term whose factor of two has been moved in the engine and in the oracle together.", "A closed form whose constant is wrong at high NTU, which shows as a ceiling never reached.", "A duty, a coefficient, a surface and a driving force that do not satisfy the equation they came from.", "Three separate branches of the code that must return one figure at a capacity ratio of zero."]'::jsonb, 2, 'The three limits named in the other options are the thin wall against the flat plate, the two ceilings, and the collapse where three branches meet.'),
  ('heattransfer', 'advanced', 'final', null, 15, 'ANTAN carries a duty of 15500000.0000 Btu an hour across an air rise of 26.000000 degF. What air mass follows?', '["2777777.7778 lb an hour.", "36660.428319 lb an hour.", "186968.1844 lb an hour.", "2483974.3590 lb an hour."]'::jsonb, 3, 'The figure 2777777.7778 is the studio bay''s air mass, 36660.428319 is ANTAN''s bare surface in ft2, and 186968.1844 is its UA.'),
  ('heattransfer', 'advanced', 'final', null, 16, 'A forced-draft bay and an induced-draft bay differ in one input. Which figures move with it?', '["The fan inlet temperature, the air density, the volume, the brake horsepower and the motor horsepower.", "The bare surface, the log mean and the air mass, since the fan sits in a different stream from the bundle it serves.", "The duty and the design ambient, since an induced fan draws the air after it has been heated.", "The barometric pressure and the air heat capacity, both of which are read at the fan inlet."]'::jsonb, 0, 'Nothing about the bundle changes. On the studio bay the fan inlet moves from 95.000000 to 125.000000 degF and the density from 0.071524401 to 0.067854412 lb per ft3.'),
  ('heattransfer', 'advanced', 'final', null, 17, 'At a barometer of 13.200000 psia the bay reports a density of 0.063880487 lb per ft3 and 648078.5374 actual ft3 a minute. What fan power goes with those?', '["84.515865 brake horsepower.", "94.119941 brake horsepower.", "103.531935 brake horsepower.", "94.003933 brake horsepower."]'::jsonb, 1, 'The figures 84.515865 and 103.531935 belong to 14.700000 and 12.000000 psia on the same sweep, and 94.003933 is the studio bay''s forced-draft fan power.'),
  ('heattransfer', 'advanced', 'final', null, 18, 'What does the air cooler report in its correction factor field, and what does the note beside it say the area is?', '["A value of 1.000000, and an area already corrected for cross flow at that value.", "An empty field, and an area the hot-day rating will correct once a check ambient is given.", "An empty field, and a counter-current-basis area that a real cross-flow unit would have to exceed.", "A value taken from the held register, and an area carrying the declared 10 percent margin."]'::jsonb, 2, 'A real cross-flow unit needs more metal than the figure printed, and how much more is not available in this repository at all.'),
  ('heattransfer', 'advanced', 'final', null, 19, 'Which of these does an air cooler answer refuse rather than compute?', '["A design ambient below the process outlet.", "A barometric pressure below the standard base of 14.700000 psia.", "An air rise larger than the process temperature drop.", "A process outlet above the process inlet."]'::jsonb, 3, 'A cooler takes the process down, and the message reads the two temperatures back so the caller can see which pair it rejected.'),
  ('heattransfer', 'advanced', 'final', null, 20, 'The air density export returns a bare NaN below absolute zero. What happens to that?', '["The bay that calls it turns it into a named refusal rather than passing it on.", "It is returned to the caller unchanged, which is the documented exception.", "It is replaced by the density at the standard base of 14.700000 psia.", "It is recorded in the held register, since a leaf correlation cannot be validated."]'::jsonb, 0, 'A leaf correlation has nowhere to put an error key, which is why that export sits outside the module''s error contract. The module documents the exception rather than making it silently.'),
  ('heattransfer', 'advanced', 'final', null, 21, 'ANTAN reports 86.879945 brake horsepower and 94.434723 motor horsepower at its design point. What separates the two figures?', '["The draft type, which puts the fan inlet at two different temperatures.", "The motor efficiency, which this module declares at 0.920000.", "The barometer of 14.300000 psia, which is applied to the shaft figure alone.", "The fan static pressure of 0.600000 inches of water, which the motor figure adds."]'::jsonb, 1, 'A motor draws more than the shaft it turns, which is why a motor efficiency above 1 is refused. The studio bay shows the same pair at 94.003933 and 102.178189.'),
  ('heattransfer', 'advanced', 'final', null, 22, 'A hot-day sheet shows a UA that drifts with the ambient while claiming a fixed surface and a fixed air mass. What does that tell a reviewer?', '["That the coefficient was taken on the bare surface rather than on the finned one.", "That the sheet was produced at more than one barometer, which moves the air mass.", "Something has been recomputed that should have been carried, so the answer is wrong before any duty is read.", "That the rating used the counter-current log mean where it should have used the hot-day one."]'::jsonb, 2, 'The surface and the air mass fix UA. On the studio bay it reads 234565.8720 Btu an hour per degF at every ambient from 86.000000 to 124.000000 degF, and on ANTAN 186968.1844.'),
  ('heattransfer', 'advanced', 'final', null, 23, 'ANTAN at a check ambient of 98.000000 degF returns a duty fraction of 1.000000 and a duty of 15500000.0000 Btu an hour. Why?', '["That is its design ambient, so the rating returns the design duty.", "That is the ambient at which its effectiveness of 0.562044 reaches its ceiling.", "That is the ambient at which its air rise of 26.000000 degF is recovered exactly.", "That is the studio bay''s design ambient, and the two bays share a design point."]'::jsonb, 0, 'The studio bay''s design ambient is 95.000000 degF, and at 98.000000 degF it is already labelled hotter than design with a fraction of 0.980645.'),
  ('heattransfer', 'advanced', 'final', null, 24, 'On the studio bay at a check ambient of 124.000000 degF the air rise is 24.387097 degF and the air outlet 148.387097 degF. What has happened to both since the design point?', '["The rise has risen from 30.000000 degF and the outlet has risen from 125.000000 degF.", "The rise has fallen from 30.000000 degF and the outlet has fallen from 125.000000 degF.", "Both have been held, because the air mass is one of the two things the plant owns.", "The rise has fallen from 30.000000 degF and the outlet has risen from 125.000000 degF."]'::jsonb, 3, 'The duty falls, so the rise across a fixed air mass falls with it, and the outlet still climbs because the ambient beneath it has risen further than the rise has fallen.'),
  ('heattransfer', 'advanced', 'final', null, 25, 'What is the engine''s stated basis for a hot-day answer?', '["The counter-current log mean at fixed UA, corrected by an F of 1.000000 for cross flow.", "Effectiveness-NTU at fixed UA and fixed air mass, with no arrangement and no F correction assumed.", "The surface equation solved at the design log mean, with the duty scaled by the ambient span.", "The 1-2 shell relation at fixed UA, which is the arrangement a finned bundle most resembles."]'::jsonb, 1, 'The effectiveness is taken from its definition at the design point, so the one number this module cannot source never enters the answer.'),
  ('heattransfer', 'advanced', 'final', null, 26, 'The duty fraction and the process outlet are the two columns that move. Which of these may be formed from them?', '["The ratio of the duty fraction to the process outlet at each ambient.", "The ratio of the process outlet to the effectiveness that produced it.", "The direction each one takes as the ambient rises.", "The rate at which the duty fraction falls per degF of ambient."]'::jsonb, 2, 'The engine computes no ratio between those columns, so a figure formed by dividing them is a figure nothing here stands behind. The direction is the finding.'),
  ('heattransfer', 'advanced', 'final', null, 27, 'A published hot-day row gives a design duty of 8000000.0000 Btu an hour with a process inlet of 180.000000 degF, an outlet of 120.000000 degF and a design ambient of 90.000000 degF. At a check ambient of 105.000000 degF what UA does it carry?', '["234565.8720 Btu an hour per degF.", "110580.3328 Btu an hour per degF.", "186968.1844 Btu an hour per degF.", "176729.1173 Btu an hour per degF."]'::jsonb, 3, 'UA is a property of the bay rather than of the check ambient. The figure 110580.3328 belongs to the published row with a design duty of 14000000.0000 Btu an hour.'),
  ('heattransfer', 'advanced', 'final', null, 28, 'What would taking the second-method log mean at the design outlet and the design air rise turn the check into?', '["A restatement, since it would no longer be formed at the answer being checked.", "A refusal, since the engine will not form a log mean at two different sets of terminals.", "A sizing, since those are the design terminals.", "An identity, since the design log mean and UA reproduce the design duty by construction."]'::jsonb, 0, 'The hot-day log mean is formed at the rated outlet and the rated air rise. That is what holding UA fixed means, and it is what lets the product be a check.'),
  ('heattransfer', 'advanced', 'final', null, 29, 'Which of these numbers can be measured out of the engine rather than taken from its source?', '["The Dittus-Boelter coefficient of 0.023000, pinned by literal.", "The specific heat behind a bay''s air balance, at 0.240000.", "The laminar Nusselt number of 3.660000.", "The declared maximum of 6 shell passes."]'::jsonb, 1, 'It falls out of the duty over the air mass and the rise on a bay''s own answer. A fitted coefficient and a declared bound cannot be recovered that way.'),
  ('heattransfer', 'advanced', 'final', null, 30, 'The fan constant implies a water density of 62.303335 lb per ft3. Where is that figure recorded, and as what?', '["In the declared constants table, as a pinned literal beside the fan constant.", "In the held register, as the one entry with an established source.", "In the published file, as a measurement rather than as a citation.", "In the engine''s fan answer, beside the brake horsepower."]'::jsonb, 2, 'The oracle''s fan route goes through pascals with that density and carries no customary constant at all, so moving the constant in both files still fails.'),
  ('heattransfer', 'advanced', 'final', null, 31, 'What does the held register entry for the Dittus-Boelter band say the engine does instead?', '["It refuses any call whose Reynolds number falls outside 2300 to 10000.", "It applies the laminar limit wherever the band cannot be confirmed for the case.", "It reports a validity band taken from the golden file, with a note that it is synthetic.", "It returns the Reynolds and the Prandtl numbers on every call so a caller can check them against a source they trust."]'::jsonb, 3, 'Nothing here grades them. That is the honest shape for a held item: the numbers a reader would need are handed over and nothing claims to have checked them.'),
  ('heattransfer', 'advanced', 'final', null, 32, 'Which of these is a declared bound this module chose rather than a limit it took from a publication?', '["The maximum of 6 shell passes in series.", "The conversion of 2.419100 from centipoise to pounds per foot per hour.", "The ceiling of 0.500000 on a parallel unit at a capacity ratio of 1.000000.", "The Prandtl exponent of 0.400000 in the heating form of the correlation."]'::jsonb, 0, 'It exists because the correction factor climbs toward one as shells are added, so an unbounded box makes any duty reachable by typing a bigger number, and the refusal says it is declared.'),
  ('heattransfer', 'advanced', 'final', null, 33, 'The other declared bound is a margin of 10 percent. What does it govern?', '["Whether a bundle diameter is reported at all, given the two layouts that are identical.", "Whether a controlling resistance verdict stands alone or carries a note telling a reader to treat two terms as jointly controlling.", "Whether a duty fraction above one is labelled as a capability rather than a delivered duty.", "Whether a film coefficient is refused for sitting too near the edge of the transition band."]'::jsonb, 1, 'A one-word verdict decided by a two percent gap is a coin toss, so below this margin the answer carries a note instead. It is a reporting threshold rather than a physical one.'),
  ('heattransfer', 'advanced', 'final', null, 34, 'A course may teach what an engine used to do. What makes such a sentence a defect instead?', '["Naming the repair that changed it, since a repair name dates the sentence.", "Carrying a figure from before the repair, since every such figure is stale.", "Reading as current behaviour rather than as an account of a former state.", "Appearing anywhere outside the engine''s own source comments."]'::jsonb, 2, 'The framing has to come from the heading above a passage or the line immediately before it. A sentence lifted out of a source comment arrives with no frame around it.'),
  ('heattransfer', 'advanced', 'final', null, 35, 'Before the repair the studio passed a hard-coded tube count into the film while printing a different count beside it. What is the general lesson recorded against that former behaviour?', '["A hard-coded input should be replaced by the value from the published file.", "A film coefficient should never be reported on the same screen as a tube count.", "A count printed beside a coefficient should carry the pass count with it.", "A screen showing two numbers that disagree about the same thing is a screen where one of them was never computed."]'::jsonb, 3, 'The fix is to close the loop rather than to choose a better constant. That is history and it is what the studio used to do.'),
  ('heattransfer', 'advanced', 'final', null, 36, 'A reviewer receives a bare surface and a hot-day duty from this module with no qualifications attached. What has been lost?', '["That the surface is on a counter-current basis, and that the rating holds effectiveness at fixed UA and fixed air mass.", "That the surface was formed on the bare tube area rather than the finned one, and that the duty is a fraction.", "That the surface carries the declared 10 percent margin, and that the duty was checked against the published file.", "That the surface was sized at the design ambient, and that the duty was rated at the same ambient."]'::jsonb, 0, 'Both qualifications are stated by the engine itself, one in an empty correction field with its note and one in the basis string on every rated answer.'),
  ('heattransfer', 'advanced', 'final', null, 37, 'Two exports in this package are called an overall coefficient. What has to travel with either one?', '["The fouling allowances behind it.", "The area it is referred to.", "The arrangement it was formed for.", "The tube count that produced its film."]'::jsonb, 1, 'This module''s is referred to the outside tube surface and says so on every answer. A second export in the production domain is referred to a stated bore instead.'),
  ('heattransfer', 'advanced', 'final', null, 38, 'This module exports 17 names in all. How many of them are frozen tables rather than functions?', '["2, which are the declared constants and the held register.", "7, one for each entry the held register carries.", "3, which are the declared constants, the declared bounds and the held register.", "12, one for each door that takes a named-argument object."]'::jsonb, 2, 'Section 20 reads the held register itself rather than quoting a count from the module''s header sentence, which is how the disagreement between 7 and six was found.'),
  ('heattransfer', 'advanced', 'final', null, 39, 'Which habit does this tier end on?', '["Compare every number on a result sheet with the published file.", "Report every number on a result sheet to the precision the engine returns.", "Take every number on a result sheet from a single door of the engine.", "Compute one number on a result sheet from the others."]'::jsonb, 3, 'A result carrying several figures has to be self-consistent, and the numbers that are not independent are the ones that catch the error.'),
  ('heattransfer', 'advanced', 'final', null, 40, 'A bundle is asked for at a layout of 60 degrees. What happens?', '["It is refused, because this module carries constants for 30, 45 and 90 degree layouts only.", "It is answered, because 60 degrees falls between two layouts the module carries.", "It is answered with a note attached, because the 45 and 90 degree constants this module carries are identical anyway.", "It is refused, because a layout angle is held for literature and cannot be given at all."]'::jsonb, 0, 'The refusal names the layouts the module does carry rather than falling back on one of them.'),
  ('heattransfer', 'advanced', 'final', null, 41, 'A bundle-to-shell clearance of -2.5 inches is given. What does the engine do?', '["It answers, treating the sign as a bundle larger than its shell.", "It refuses, because the clearance must be zero or positive inches.", "It answers at a clearance of 2.500000 inches, which is the studio default.", "It refuses, because a clearance is an input the module holds for literature."]'::jsonb, 1, 'A negative one would describe a shell narrower than the bundle inside it, and the message names the box rather than the geometry.'),
  ('heattransfer', 'advanced', 'final', null, 42, 'A bay whose process enters at 250.000000 degF is asked for a rating at a check ambient of 260.000000 degF. What comes back?', '["A duty fraction of zero, with the process outlet held at the process inlet.", "A negative duty fraction, which the engine labels hotter than design.", "A refusal, because the air is not colder than the process inlet, so the cooler has no driving force at all.", "A rating at the highest ambient the sweep carries, which is 124.000000 degF."]'::jsonb, 2, 'The refusal states the two temperatures rather than returning a duty of zero and leaving a reader to interpret it.');
